/**
 * Default adapters for standalone mode (no platform-hosted shell). Auth,
 * permissions, and tenant are real capabilities this phase deliberately does
 * not implement (no Keycloak, RBAC backend, or tenant system yet), so they
 * report "unavailable" rather than fabricating a fake session/grant/tenant.
 * Navigation has no such backend dependency, so it works standalone via the
 * browser's own History API.
 */
export function createStandaloneAuthAdapter(
  reason = AUTH_UNAVAILABLE,
): AuthAdapter {
  return {
    getSnapshot: () => null,
    subscribe: () => () => {},
    signIn: () =>
      Promise.reject(
        new PlatformCapabilityUnavailableError('auth', reason),
      ),
    signOut: () =>
      Promise.reject(
        new PlatformCapabilityUnavailableError('auth', reason),
      ),
  };
}

export function createStandalonePermissionsAdapter(): PermissionsAdapter {
  return {
    getSnapshot: () => null,
    subscribe: () => () => {},
  };
}

export function createStandaloneTenantAdapter(): TenantAdapter {
  return {
    getSnapshot: () => null,
    subscribe: () => () => {},
  };
}

export function resolvePlatformRuntime(
  mode: PlatformAppIdentity['mode'],
  host: PlatformHostContext | null,
): ResolvedPlatformRuntime {
  switch (mode) {
    case 'standalone':
      return { runtimeMode: 'standalone' };
    case 'platform-mfe':
      if (!host) {
        throw new PlatformRuntimeUnavailableError(mode);
      }
      return { runtimeMode: 'hosted', adapters: host.adapters };
    case 'standalone-and-mfe':
      return host
        ? { runtimeMode: 'hosted', adapters: host.adapters }
        : { runtimeMode: 'standalone' };
    default:
      // platform-app.json is hand-editable after generation, so this is a
      // real boundary against a malformed/unknown mode, not a can't-happen branch.
      throw new Error(`Unknown platform-app.json mode: "${String(mode)}"`);
  }
}
